SELECT

FROM ai_business_trigger_log
WHERE tenant_id = #{tenantId}

  AND trigger_id = #{triggerId}

ORDER BY execute_time DESC, id DESC

SELECT COUNT(1)
FROM ai_business_trigger_log
WHERE tenant_id = #{tenantId}
  AND trigger_id = #{triggerId}
  AND record_id = #{recordId}
  AND event_type = #{eventType}
  AND execute_status IN ('SUCCESS', 'TODO')
  AND execute_time >= #{sinceTime}

SELECT 
FROM ai_business_trigger_log
WHERE tenant_id = #{tenantId}
  AND trigger_id = #{triggerId}
  AND event_id = #{eventId}
LIMIT 1

SELECT 
FROM ai_business_trigger_log
WHERE tenant_id = #{tenantId}
  AND id = #{id}
LIMIT 1
